package com.grimyherblorelevels;

import java.util.HashSet;
import java.util.Set;
import net.runelite.api.gameval.ItemID;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/**
 * The herb table is the only part of this plugin that can be wrong without anything failing, so it
 * is pinned here. Levels are from the OSRS Wiki herb cleaning table.
 */
public class GrimyHerbTest
{
	@Test
	public void tableCoversEveryGrimyHerb()
	{
		assertEquals(23, GrimyHerb.values().length);
	}

	@Test
	public void itemIdsAreUnique()
	{
		final Set<Integer> seen = new HashSet<>();
		for (final GrimyHerb herb : GrimyHerb.values())
		{
			assertTrue("duplicate item id for " + herb, seen.add(herb.getItemId()));
		}
	}

	@Test
	public void levelsAreSaneAndMatchTheirText()
	{
		for (final GrimyHerb herb : GrimyHerb.values())
		{
			assertTrue(herb + " has an out of range level", herb.getLevel() >= 1 && herb.getLevel() <= 99);
			assertEquals("lvl " + herb.getLevel(), herb.getLevelText());
		}
	}

	@Test
	public void levelTextIsPrefixed()
	{
		assertEquals("lvl 3", GrimyHerb.GUAM.getLevelText());
		assertEquals("lvl 75", GrimyHerb.TORSTOL.getLevelText());
	}

	@Test
	public void lookupResolvesKnownHerbs()
	{
		assertSame(GrimyHerb.RANARR_WEED, GrimyHerb.forItemId(ItemID.UNIDENTIFIED_RANARR));
		assertSame(GrimyHerb.TORSTOL, GrimyHerb.forItemId(ItemID.UNIDENTIFIED_TORSTOL));
		assertSame(GrimyHerb.NOXIFER, GrimyHerb.forItemId(ItemID.RAIDS_GRIMY_NOXIFER));
	}

	@Test
	public void lookupIgnoresNonHerbs()
	{
		// Clean herbs, unrelated items and the non-herb UNIDENTIFIED_* entries must never match.
		assertNull(GrimyHerb.forItemId(ItemID.RANARR_WEED));
		assertNull(GrimyHerb.forItemId(ItemID.UNIDENTIFIED_POWDER));
		assertNull(GrimyHerb.forItemId(ItemID.UNIDENTIFIED_LIQUID));
		assertNull(GrimyHerb.forItemId(-1));
	}

	@Test
	public void spotChecksAgainstTheWiki()
	{
		assertEquals(3, GrimyHerb.GUAM.getLevel());
		assertEquals(5, GrimyHerb.MARRENTILL.getLevel());
		assertEquals(25, GrimyHerb.RANARR_WEED.getLevel());
		assertEquals(47, GrimyHerb.GOLPAR.getLevel());
		assertEquals(52, GrimyHerb.BUCHU_LEAF.getLevel());
		assertEquals(58, GrimyHerb.HUASCA.getLevel());
		assertEquals(59, GrimyHerb.SNAPDRAGON.getLevel());
		assertEquals(60, GrimyHerb.NOXIFER.getLevel());
		assertEquals(75, GrimyHerb.TORSTOL.getLevel());

		// The Jungle Potion herbs are all cleanable at 3.
		assertEquals(3, GrimyHerb.SNAKE_WEED.getLevel());
		assertEquals(3, GrimyHerb.ROGUES_PURSE.getLevel());
	}
}

