package com.grimyherblorelevels;

import com.google.inject.Provides;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@Slf4j
@PluginDescriptor(
	name = "Grimy Herblore Levels",
	description = "Marks grimy herbs your Herblore level is too low to clean and prints the level they need.",
	tags = {"herblore", "herb", "grimy", "clean", "bank", "skilling"}
)
public class GrimyHerbloreLevelsPlugin extends Plugin
{
	@Inject
	private OverlayManager overlayManager;

	@Inject
	private GrimyHerbOverlay overlay;

	@Override
	protected void startUp()
	{
		overlayManager.add(overlay);
		log.debug("Grimy Herblore Levels started");
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		log.debug("Grimy Herblore Levels stopped");
	}

	@Provides
	GrimyHerbloreLevelsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(GrimyHerbloreLevelsConfig.class);
	}
}

