package com.grimyherblorelevels;

import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Skill;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.WidgetItemOverlay;
import net.runelite.client.ui.overlay.components.TextComponent;

/**
 * Marks every grimy herb the player is not yet able to clean.
 *
 * <p>A {@link WidgetItemOverlay} always draws <em>after</em> the item sprite, so the box cannot
 * simply be painted underneath it. Instead the box is filled over the slot and the herb is then
 * repainted on top of it from {@link ItemManager}, which puts the sprite back in front and leaves
 * the colour reading as a backdrop rather than a wash over the herb.
 */
class GrimyHerbOverlay extends WidgetItemOverlay
{
	private final Client client;
	private final ItemManager itemManager;
	private final GrimyHerbloreLevelsConfig config;

	/**
	 * Reused rather than allocated per item: {@link #renderItemOverlay} runs once per visible herb
	 * per frame, and a full bank tab of grimy herbs would otherwise churn a component every frame.
	 * Safe because overlays only ever render on the client thread.
	 */
	private final TextComponent textComponent = new TextComponent();

	@Inject
	GrimyHerbOverlay(Client client, ItemManager itemManager, GrimyHerbloreLevelsConfig config)
	{
		this.client = client;
		this.itemManager = itemManager;
		this.config = config;

		// Note: WidgetItemOverlay hard-overrides setLayer/setPosition to throw, so the layer and
		// position are whatever the superclass constructor picked (MANUAL/DYNAMIC). Don't set them.
		textComponent.setFont(FontManager.getRunescapeSmallFont());
		textComponent.setOutline(true);

		// showOnInventory() already covers the inventory, the bank-side inventory, the deposit box,
		// shop and Grand Exchange side panels, the trade window and the seed vault deposit screen;
		// showOnBank() covers the bank item container and the group ironman shared bank. The explicit
		// list below is only the handful of item-bearing interfaces neither of those reaches.
		showOnInventory();
		showOnBank();
		showOnInterfaces(
			InterfaceID.TRADECONFIRM,
			InterfaceID.GE_OFFERS,
			InterfaceID.GE_COLLECT,
			InterfaceID.SHARED_BANK_SIDE);
	}

	@Override
	public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem itemWidget)
	{
		final GrimyHerb herb = GrimyHerb.forItemId(itemId);
		if (herb == null)
		{
			return;
		}

		final int herbloreLevel = config.useBoostedLevel()
			? client.getBoostedSkillLevel(Skill.HERBLORE)
			: client.getRealSkillLevel(Skill.HERBLORE);

		// A level of 0 means the skill array has not been populated yet (not logged in), which would
		// otherwise paint every herb in the interface red.
		if (herbloreLevel <= 0 || herbloreLevel >= herb.getLevel())
		{
			return;
		}

		final Rectangle bounds = itemWidget.getCanvasBounds();

		graphics.setColor(config.lockedColor());
		graphics.fill(bounds);

		// Put the herb back in front of the box we just painted over it. Quantity is passed through so
		// the bank's stack count is repainted too — it was covered by the fill along with the sprite.
		// Passing stackable only when the count is actually shown keeps single items from gaining a
		// spurious "1". ItemManager renders this synchronously here: its loader goes through
		// ClientThread.invoke, which runs inline when it is already on the client thread, as overlays
		// always are. So there is no unpainted first frame to flicker through.
		final int quantity = itemWidget.getQuantity();
		final BufferedImage herbImage = itemManager.getImage(itemId, quantity, quantity > 1);
		if (herbImage != null)
		{
			graphics.drawImage(herbImage, bounds.x, bounds.y, null);
		}

		if (config.showLevelText())
		{
			// Bottom-left: the game draws stack quantities in the top-left corner.
			textComponent.setText(herb.getLevelText());
			textComponent.setColor(config.levelTextColor());
			textComponent.setPosition(new Point(bounds.x, bounds.y + bounds.height));
			textComponent.render(graphics);
		}
	}
}

