package com.grimyherblorelevels;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(GrimyHerbloreLevelsConfig.GROUP)
public interface GrimyHerbloreLevelsConfig extends Config
{
	String GROUP = "grimyherblorelevels";

	@Alpha
	@ConfigItem(
		keyName = "lockedColor",
		name = "Highlight colour",
		description = "Colour and opacity of the box drawn behind herbs above your Herblore level.",
		position = 0
	)
	default Color lockedColor()
	{
		return new Color(255, 0, 0, 80);
	}

	@ConfigItem(
		keyName = "showLevelText",
		name = "Show required level",
		description = "Print the Herblore level needed to clean the herb onto the item.",
		position = 1
	)
	default boolean showLevelText()
	{
		return true;
	}

	@Alpha
	@ConfigItem(
		keyName = "levelTextColor",
		name = "Level text colour",
		description = "Colour of the required level printed onto the herb.",
		position = 2
	)
	default Color levelTextColor()
	{
		return Color.WHITE;
	}

	@ConfigItem(
		keyName = "useBoostedLevel",
		name = "Account for stat boosts",
		description = "Compare against your boosted Herblore level, which is what the game actually checks when cleaning. Turn off to always compare against your base level.",
		position = 3
	)
	default boolean useBoostedLevel()
	{
		return true;
	}
}

