package com.grimyherblorelevels;

import com.google.common.collect.ImmutableMap;
import java.util.Map;
import lombok.Getter;
import net.runelite.api.gameval.ItemID;

/**
 * Every grimy herb in the game, paired with the Herblore level needed to clean it.
 *
 * <p>Note that {@link ItemID} (the gameval one, not the deprecated {@code net.runelite.api.ItemID})
 * names grimy herbs after their cache names — {@code UNIDENTIFIED_*} rather than {@code GRIMY_*} —
 * and only the three Chambers of Xeric herbs carry the {@code RAIDS_GRIMY_*} prefix.
 *
 * <p>The level table is inlined rather than read from RuneLite's own
 * {@code skillcalculator.skills.HerbloreAction}: that enum lives in another plugin's package, and
 * its item ids are the <em>clean</em> herbs, not the grimy ones we actually need to match on.
 */
@Getter
enum GrimyHerb
{
	GUAM(ItemID.UNIDENTIFIED_GUAM, 3),
	MARRENTILL(ItemID.UNIDENTIFIED_MARENTILL, 5),
	TARROMIN(ItemID.UNIDENTIFIED_TARROMIN, 11),
	HARRALANDER(ItemID.UNIDENTIFIED_HARRALANDER, 20),
	RANARR_WEED(ItemID.UNIDENTIFIED_RANARR, 25),
	TOADFLAX(ItemID.UNIDENTIFIED_TOADFLAX, 30),
	IRIT_LEAF(ItemID.UNIDENTIFIED_IRIT, 40),
	AVANTOE(ItemID.UNIDENTIFIED_AVANTOE, 48),
	KWUARM(ItemID.UNIDENTIFIED_KWUARM, 54),
	HUASCA(ItemID.UNIDENTIFIED_HUASCA, 58),
	SNAPDRAGON(ItemID.UNIDENTIFIED_SNAPDRAGON, 59),
	CADANTINE(ItemID.UNIDENTIFIED_CADANTINE, 65),
	LANTADYME(ItemID.UNIDENTIFIED_LANTADYME, 67),
	DWARF_WEED(ItemID.UNIDENTIFIED_DWARF_WEED, 70),
	TORSTOL(ItemID.UNIDENTIFIED_TORSTOL, 75),

	// Jungle Potion / Tai Bwo Wannai herbs — all cleanable at 3.
	SNAKE_WEED(ItemID.UNIDENTIFIED_SNAKE_WEED, 3),
	ARDRIGAL(ItemID.UNIDENTIFIED_ARDRIGAL, 3),
	SITO_FOIL(ItemID.UNIDENTIFIED_SITO_FOIL, 3),
	VOLENCIA_MOSS(ItemID.UNIDENTIFIED_VOLENCIA_MOSS, 3),
	ROGUES_PURSE(ItemID.UNIDENTIFIED_ROGUES_PURSE, 3),

	// Chambers of Xeric herbs.
	GOLPAR(ItemID.RAIDS_GRIMY_GOLPAR, 47),
	BUCHU_LEAF(ItemID.RAIDS_GRIMY_BUCHULEAF, 52),
	NOXIFER(ItemID.RAIDS_GRIMY_NOXIFER, 60);

	private final int itemId;
	private final int level;

	/**
	 * The label rendered onto the item, e.g. {@code "lvl 75"}. Precomputed because the overlay draws
	 * it once per herb per frame, and concatenating on every one of those would be pure garbage.
	 */
	private final String levelText;

	GrimyHerb(int itemId, int level)
	{
		this.itemId = itemId;
		this.level = level;
		this.levelText = "lvl " + level;
	}

	private static final Map<Integer, GrimyHerb> BY_ITEM_ID;

	static
	{
		// ImmutableMap.Builder rejects duplicate keys, so a copy-paste slip in the table above fails
		// loudly at class-init instead of silently shadowing a herb.
		final ImmutableMap.Builder<Integer, GrimyHerb> builder = ImmutableMap.builder();
		for (final GrimyHerb herb : values())
		{
			builder.put(herb.itemId, herb);
		}
		BY_ITEM_ID = builder.build();
	}

	/**
	 * @return the herb for an exact item id, or null if the item is not a grimy herb.
	 * <p>
	 * Deliberately not canonicalized: bank placeholders and noted herbs carry their own item ids, so
	 * an exact match skips both — which is what we want, since you own zero of a placeholder and a
	 * noted herb cannot be cleaned at all.
	 */
	static GrimyHerb forItemId(int itemId)
	{
		return BY_ITEM_ID.get(itemId);
	}
}
